from pathlib import Path
import csv,json,html
p=Path(__file__).resolve().parent
s=json.loads((p/'summary.json').read_text())
rows=list(csv.DictReader((p/'hcp_prioritization.csv').open()))
bars=''.join(f'<p>{k} <b>{v}</b></p><div class="track"><div style="width:{v/240*100}%"></div></div>' for k,v in s['segments'].items())
table=''.join('<tr>'+''.join('<td>'+html.escape(r[k])+'</td>' for k in ['hcp_name','region','segment','pre_rx','post_rx','priority_score'])+'</tr>' for r in rows[:15])
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HCP Commercial Analytics</title><style>body{font:16px system-ui;background:#f1f5f9;color:#142b40;margin:0}main{max-width:1100px;margin:auto;padding:40px 24px}h1{font-size:38px;margin-bottom:8px}.sub{color:#526579}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:28px 0}article,section{background:white;border:1px solid #dbe3ec;border-radius:14px;padding:22px;margin-bottom:20px}article b{display:block;font-size:30px;color:#087f8c}article span{font-size:14px} .track{height:12px;background:#e7edf3;border-radius:8px;overflow:hidden}.track div{height:100%;background:#087f8c}p b{float:right}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;padding:12px;border-bottom:1px solid #e7edf3}.overflow{overflow:auto}.notice{background:#fff3cd;padding:14px;border-radius:8px}footer{font-size:13px;color:#526579}@media(max-width:700px){.cards{grid-template-columns:repeat(2,1fr)}h1{font-size:28px}}</style><main><div class="sub">PORTFOLIO CASE STUDY / JANâ€“JUN 2026</div><h1>HCP Commercial Analytics</h1><p class="sub">Physician segmentation & sales-rep prioritization</p><div class="notice">Synthetic data â€¢ Descriptive analysis â€¢ No measured campaign ROI or causal effect</div><div class="cards">CARDS</div><section><h2>Physician segments</h2>BARS</section><section><h2>Outreach funnel</h2><p>240 HCPs â†’ 160 alerted â†’ 120 contacted â†’ 98 contacted post-prescribers</p><p class="sub">Post prescribing does not prove an outreach response.</p></section><section><h2>Top 15 opportunities</h2><p class="sub">Heuristic score: competitor dominance + decline + current prescribing + no contact.</p><div class="overflow"><table><thead><tr><th>HCP</th><th>Region</th><th>Segment</th><th>Pre Rx</th><th>Post Rx</th><th>Score</th></tr></thead><tbody>ROWS</tbody></table></div></section><footer>Static snapshot generated from the SQL output. Re-run analysis and regenerate this report after changing source data. Equal three-month pre/post windows; zero-baseline lift is undefined.</footer></main></html>'''
cards=''.join(f'<article><b>{v}</b><span>{k}</span></article>' for k,v in [('HCPs',240),('Pre-period brand Rx',s['pre_rx']),('Post-period brand Rx',s['post_rx']),('Observed lift',f"{(s['post_rx']/s['pre_rx']-1)*100:.1f}%")])
(p/'dashboard.html').write_text(page.replace('CARDS',cards).replace('BARS',bars).replace('ROWS',table),encoding='utf-8')
